# 기술지침 표에 없는 물질에 대해 별도 조사한 보충값
# 형식: CAS -> {"label": "ERPG-2"|"AEGL-2"|"PAC-2"|"IDLH"|"N/A", "value": str, "source": str}
SUPPLEMENTARY_TABLE = {'64-19-7': {'label': 'PAC-2', 'value': '86 mg/m3', 'source': 'NOAA PAC(Protective Action Criteria) Rev.27, Table 4 (2012.2) - 기술지침 표에 미수록되어 보충조사'}, '67-64-1': {'label': 'PAC-2', 'value': '7,600 mg/m3', 'source': 'NOAA PAC(Protective Action Criteria) Rev.27, Table 4 (2012.2) - 기술지침 표에 미수록되어 보충조사'}, '7553-56-2': {'label': 'ERPG-2', 'value': '0.5 ppm', 'source': 'AIHA 2016 ERPG/WEEL Handbook - 기술지침 표에 미수록되어 보충조사'}, '7727-37-9': {'label': 'N/A', 'value': '', 'source': '질소는 불활성 질식성기체로 ERPG/AEGL/PAC/IDLH 독성 끝점농도가 설정되어 있지 않음(산소치환에 의한 질식 위험만 존재)'}}


def lookup_endpoint(cas):
    """CAS번호로 위험노출수준(끝점농도)을 조회.
    우선순위: 기술지침 본표의 ERPG-2 > AEGL-2 > PAC-2 > IDLH, 없으면 SUPPLEMENTARY_TABLE.
    반환: (표시문자열 또는 None, 출처문자열 또는 None, status)
      status: "table" (기술지침 본표) | "supplementary" (보충조사) | "na" (해당없음) | "not_found"
    """
    rec = ENDPOINT_TABLE.get(cas)
    if rec:
        for label in PRIORITY:
            if label in rec:
                value, unit, name_en = rec[label]
                return (f"{label} {value}{unit}",
                        "화학물질안전원 「사고시나리오 선정 및 위험도 분석에 관한 기술지침」 <붙임1>",
                        "table")
    sup = SUPPLEMENTARY_TABLE.get(cas)
    if sup:
        if sup["label"] == "N/A":
            return ("해당없음(불활성기체)", sup["source"], "na")
        return (f"{sup['label']} {sup['value']}", sup["source"], "supplementary")
    return (None, None, "not_found")
